const MAX_PER_RUN = 200;
const ne = (v) => v !== undefined && v !== null && String(v).trim() !== '';

const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if (!ne(r.email)) continue;
  if (!ne(r.provider_id)) continue;
  if (ne(r.sendability)) continue;
  if (ne(r.email_sent_at)) continue;
  const st = String(r.email_send_status || '').toLowerCase();
  if (st === 'unsubscribed' || st === 'bounced') continue;
  out.push({ json: r });
}

console.log(`Pre-filter queue: ${out.length} candidates, checking ${Math.min(out.length, MAX_PER_RUN)}`);
return out.slice(0, MAX_PER_RUN);

// Grade on what can actually be proven, then sanity-check the DOMAIN ITSELF.
//
// v1 enrichment parsed job titles as company names and built domains from them:
//   'Nonprofit Leader'      -> anne.friedman@leader.com
//   'Program Director'      -> kellianne@programdirector.org
//   'The New York Foundling' -> pauline.alama@the.com
// Those domains are real and decades old, so format + MX both pass and they
// would grade sendable. Emailing them means cold-pitching uninvolved companies.

const REQUIRE_COMPANY_MATCH = true;   // set false to allow sends where company_name is blank

const lead = $('Loop Over Emails').item.json;
const v = $json || {};

const email = String(lead.email || '').toLowerCase().trim();
const local = email.split('@')[0] || '';
const domain = (email.split('@')[1] || '').toLowerCase();
const domainRoot = domain
  .replace(/\.(com|org|net|edu|gov|io|co|us|uk|ca|info|biz|ngo|charity)(\.[a-z]{2})?$/, '')
  .replace(/[^a-z0-9]/g, '');

// ---------- role accounts ----------
const ROLE = ['info','admin','administrator','contact','support','hello','office','mail','team','sales','billing','help','noreply','no-reply','webmaster','postmaster','enquiries','inquiries','general','donations','volunteer',
  // added 13 Oct: assistance@ and press@ were grading sendable_unverified
  'assistance','press','media','pr','marketing','hr','careers','jobs','service','services','customerservice','reception','secretary','accounts','finance','legal','privacy','abuse','security','feedback','subscribe','newsletter','communications','development','grants','outreach'];
const isRole = ROLE.includes(local) || /^(info|admin|contact|support|office|hello|press|media|assistance|enquir|inquir)[._-]/.test(local);

// ---------- junk domain guard ----------
// Words that describe a JOB, not an employer.
const ROLE_WORDS = new Set(['director','directors','leader','leaders','leadership','manager','management','executive','officer','president','founder','cofounder','co','ceo','coo','cfo','cto','chair','chairman','board','consultant','consulting','strategist','specialist','coordinator','administrator','administration','program','programs','development','fundraising','fundraiser','grant','grants','writer','writing','nonprofit','non','profit','volunteer','entrepreneur','inventor','professional','freelance','independent','self','employed','retired','advisor','adviser','principal','owner','partner','associate','analyst','engineer','designer','marketing','sales','operations','recruiter','student','intern','philanthropy','philanthropist','relations','affairs','outreach','engagement','strategy','strategic']);

const STOPWORDS = new Set(['the','of','for','and','a','an','at','in','on','to','inc','llc','ltd','corp','corporation','co','company','group','holdings','plc','org','organization','organisation']);

const rawTokens = String(lead.company_name || '')
  .toLowerCase()
  .replace(/[^a-z0-9\s]/g, ' ')
  .split(/\s+/)
  .filter(Boolean);

const meaningful = rawTokens.filter(t => !STOPWORDS.has(t));
const distinctive = meaningful.filter(t => !ROLE_WORDS.has(t));

const hasCompany = rawTokens.length > 0;
// A 'company' made only of job words is a job title, not an employer.
const companyIsJobTitle = hasCompany && distinctive.length === 0;

// Does the domain plausibly belong to this organisation?
const acronym = rawTokens.map(t => t[0]).join('');
const meaningfulAcronym = meaningful.map(t => t[0]).join('');
const joined = meaningful.join('');

let domainMatches = false;
if (domainRoot) {
  if (distinctive.some(t => t.length >= 4 && domainRoot.includes(t))) domainMatches = true;
  else if (distinctive.some(t => t.length === 3 && domainRoot === t)) domainMatches = true;
  else if (domainRoot === acronym && acronym.length >= 3) domainMatches = true;
  else if (domainRoot === meaningfulAcronym && meaningfulAcronym.length >= 3) domainMatches = true;
  else if (joined && (joined.includes(domainRoot) || domainRoot.includes(joined))) domainMatches = true;
}

// ---------- API signals ----------
const validFormat = v.validFormat === true;
const validMx = v.validMx === true;
const isDisposable = v.isDisposable === true;
const smtp = (v.validSmtp === true) ? 'confirmed' : (v.validSmtp === false ? 'rejected' : 'unknown');

let ageYears = null;
try { if (v.domainAge && v.domainAge.ageInYears != null) ageYears = Number(v.domainAge.ageInYears); } catch (e) {}
const newDomain = ageYears !== null && ageYears < 0.25;

const apiFailed = !!v.error || (v.validFormat === undefined && v.validMx === undefined);

// ---------- provenance guard ----------
// The domainMatches test above compares the domain to company_name. v1 built
// company_domain AND email FROM company_name, so a fabricated domain always
// 'matches' it. String similarity structurally cannot catch that -- only
// provenance can. Trust a domain only where something actually evidenced it.
const emailSrc = String(lead.email_source || '').toLowerCase();
const domainSrc = String(lead.company_domain_source || '').trim();
const unevidencedDomain = /unevidenced|pattern_guess/.test(emailSrc) && !domainSrc;

// Three tiers of provenance, not two:
//   OBSERVED  - someone saw this address written down (site scrape, verified page)
//   GUESSED   - the DOMAIN is real but the MAILBOX was assembled from a name
//               pattern (osint_pattern). This is where the remaining bounces
//               live: arthritis.org is real, brian.simard@ was invented.
//   FABRICATED- the domain was invented too (pattern_guess) -> junk_domain above
const mailboxObserved = /site_scrape|scrape_verified|_verified|manual/.test(emailSrc);
const guessedMailbox = !mailboxObserved && /pattern|guess/.test(emailSrc);

// ---------- decision ----------
let sendability, confidence, note = '';

if (apiFailed) { sendability = 'unknown'; confidence = 0; }
else if (!validFormat) { sendability = 'do_not_send'; confidence = 0; }
else if (isDisposable) { sendability = 'do_not_send'; confidence = 0; }
else if (!validMx) { sendability = 'do_not_send'; confidence = 0; }
else if (companyIsJobTitle) { sendability = 'junk_domain'; confidence = 0; note = 'company_name is a job title'; }
else if (hasCompany && !domainMatches) { sendability = 'junk_domain'; confidence = 0; note = 'domain unrelated to company_name'; }
else if (unevidencedDomain) { sendability = 'junk_domain'; confidence = 0; note = 'domain never evidenced - pattern guess'; }
else if (!hasCompany && REQUIRE_COMPANY_MATCH) { sendability = 'hold_no_company'; confidence = 0; note = 'no company_name to verify domain against'; }
else if (smtp === 'rejected') { sendability = 'likely_invalid'; confidence = 10; }
else if (isRole) { sendability = 'role_account'; confidence = 40; }
else if (newDomain) { sendability = 'risky_new_domain'; confidence = 35; }
// 'sendable' (smtp=confirmed, confidence 90) is RETIRED. Six of the sixteen
// bounces on 14-17 Sep carried exactly that grade. The SMTP probe was
// confirming catch-all domains - servers that accept every recipient at the
// edge and reject afterwards - not real mailboxes. It read as the safest
// grade while carrying no more assurance than the one below it, so everything
// with good MX now grades the same and the bounce handler decides the rest.
else if (guessedMailbox) { sendability = 'guessed_mailbox'; confidence = 30; note = 'real domain, mailbox never observed (' + emailSrc + ')'; }
else { sendability = 'sendable_unverified'; confidence = 60; }

return { json: {
  provider_id: lead.provider_id,
  email_check_result: apiFailed ? 'error' : `format=${validFormat} mx=${validMx} smtp=${smtp} disposable=${isDisposable}${note ? ' | ' + note : ''}`,
  email_is_role: isRole,
  email_verified: smtp === 'confirmed',
  email_confidence: confidence,
  sendability: sendability,
  domain_age_years: ageYears === null ? '' : ageYears,
  email_verified_at: new Date().toISOString()
}};

// Grade Sendability runs once per batch, so $(...).all() only returns the LAST
// batch. Walk every run index to get the true total.
let rows = [];
for (let r = 0; r < 500; r++) {
  let batch;
  try { batch = $('Grade Sendability').all(0, r); } catch (e) { break; }
  if (!batch || batch.length === 0) break;
  rows.push(...batch.map(i => i.json));
}

const tally = {};
for (const r of rows) {
  const k = r.sendability || 'unknown';
  tally[k] = (tally[k] || 0) + 1;
}

return [{ json: { run_id: $execution.id, finished_at: new Date().toISOString(), graded_this_run: rows.length, by_sendability: tally }}];
